pub fn all(&self) -> bool {
        self.ensure_invariant();
        if self.nbits == 0 {
            return true;
        }
        let mut blocks = self.blocks();
        let last = blocks.next_back().unwrap();
        let mask = self.last_block_with_mask().unwrap().1;
        blocks.all(|w| *w == !B::zero()) && (last == mask)
    }

