pub fn to_bytes(&self) -> Vec<u8> {
        let mut bytes = Vec::with_capacity((self.nbits + 7) / 8);
        let mut current_byte = 0u8;
        let mut bit_idx = 0;

        for i in 0..self.nbits {
            if self.get(i).unwrap() {
                current_byte |= 1 << (7 - bit_idx);
            }
            bit_idx += 1;
            if bit_idx == 8 {
                bytes.push(current_byte);
                current_byte = 0;
                bit_idx = 0;
            }
        }

        if bit_idx != 0 {
            bytes.push(current_byte);
        }

        bytes
    }

